import React, { useState, useEffect } from 'react';
import './App.css';

function App() {
  // --- ESTADOS DE SEGURIDAD Y LOGIN ---
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');

  // --- ESTADOS DE PANTALLA ---
  const [pantalla, setPantalla] = useState('catalogo'); 
  const [productos, setProductos] = useState([]);

  const [ventasDelDia, setVentasDelDia] = useState(() => {
    const guardadas = localStorage.getItem('ventas_paisita');
    return guardadas ? JSON.parse(guardadas) : [];
  });

  const [fechaHoy] = useState(() => {
    return new Date().toLocaleDateString('es-CO', { 
      weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' 
    });
  });

  // --- ESTADOS DEL FORMULARIO ---
  const [nombre, setNombre] = useState('');
  const [categoria, setCategoria] = useState('');
  const [imagenUrl, setImagenUrl] = useState('');
  const [precioCosto, setPrecioCosto] = useState('');
  const [impuesto, setImpuesto] = useState('19'); 
  const [precioVenta, setPrecioVenta] = useState('');
  const [stock, setStock] = useState('');

  // --- EFECTOS ---
  useEffect(() => {
    localStorage.setItem('ventas_paisita', JSON.stringify(ventasDelDia));
  }, [ventasDelDia]);

  useEffect(() => {
    if (isLoggedIn) {
      obtenerInventarioBackend();
    }
  }, [isLoggedIn]);

  // --- FUNCIONES DE LÓGICA Y CONEXIÓN ---
  const obtenerInventarioBackend = async () => {
    try {
      const respuesta = await fetch('http://localhost:8080/api/productos');
      if (respuesta.ok) {
        const datos = await respuesta.json();
        setProductos(datos);
      }
    } catch (error) {
      console.error("Error al sincronizar con Spring Boot:", error);
    }
  };

  const handleBorrarTodo = async () => {
    if (window.confirm("🚨 ¿ATENCIÓN! ¿Estás seguro de que deseas ELIMINAR TODOS los productos de la base de datos? Esta acción no se puede deshacer.")) {
      try {
        const respuesta = await fetch('http://localhost:8080/api/productos/vaciar', { method: 'DELETE' });
        if (respuesta.ok) {
          alert("Base de datos vaciada con éxito.");
          setProductos([]);
          setVentasDelDia([]);
          localStorage.removeItem('ventas_paisita');
        } else {
          alert("El backend rechazó la solicitud de borrado.");
        }
      } catch (error) {
        alert("Error de conexión al intentar borrar los datos.");
      }
    }
  };

  const cambiarStockManual = async (producto) => {
    const nuevoStockString = prompt(`Modificar existencias de: ${producto.nombre}\nCantidad actual: ${producto.stock} uds.\n\nEscribe el nuevo stock total:`, producto.stock);

    if (nuevoStockString === null) return;

    const nuevoStockNum = parseInt(nuevoStockString, 10);
    if (isNaN(nuevoStockNum) || nuevoStockNum < 0) {
      alert("Por favor ingresa un número entero válido y mayor o igual a cero.");
      return;
    }

    const productoActualizado = { ...producto, stock: nuevoStockNum };

    try {
      const respuesta = await fetch('http://localhost:8080/api/productos', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(productoActualizado)
      });

      if (respuesta.ok) {
        obtenerInventarioBackend();
      } else {
        alert("No se pudo actualizar el stock en el servidor.");
      }
    } catch (error) {
      alert("Error de red al actualizar stock.");
    }
  };

  const handleGuardar = async (e) => {
    e.preventDefault();

    const productoExistente = productos.find(
      (p) => p.nombre.toLowerCase().trim() === nombre.toLowerCase().trim()
    );

    if (productoExistente) {
      alert(`El producto "${nombre}" ya existe en el catálogo. Usa el botón "Modificar Stock" en la tarjeta correspondiente para alterar sus unidades.`);
      setPantalla('catalogo');
      return;
    }

    const nuevoProducto = {
      nombre: nombre.trim(),
      categoria,
      imagenUrl: imagenUrl || 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c',
      precioCosto: parseFloat(precioCosto || 0),
      impuesto: parseFloat(impuesto || 0),
      precioVenta: parseFloat(precioVenta || 0),
      stock: parseInt(stock || 0)
    };

    try {
      const respuesta = await fetch('http://localhost:8080/api/productos', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(nuevoProducto)
      });

      if (respuesta.ok) {
        alert("¡Producto inyectado correctamente!");
        setNombre(''); setCategoria(''); setImagenUrl(''); setPrecioCosto(''); setPrecioVenta(''); setStock('');
        obtenerInventarioBackend();
        setPantalla('catalogo');
      }
    } catch (error) {
      alert("Error de conexión con el backend.");
    }
  };

  const registrarVenta = (producto) => {
    if (producto.stock <= 0) {
      alert(`¡Alerta! Sin existencias de ${producto.nombre}.`);
      return;
    }

    const inventarioActualizado = productos.map((p) => {
      if (p.id === producto.id) return { ...p, stock: p.stock - 1 };
      return p;
    });
    setProductos(inventarioActualizado);

    const costoRealConIva = (producto.precioCosto || 0) * (1 + (producto.impuesto || 0) / 100);
    const gananciaNetaGenerada = (producto.precioVenta || 0) - costoRealConIva;

    const nuevaVenta = {
      id: Date.now(),
      nombre: producto.nombre,
      precioVenta: producto.precioVenta || 0,
      costoConIva: costoRealConIva,
      gananciaNeta: gananciaNetaGenerada,
      hora: new Date().toLocaleTimeString('es-CO', { hour: '2-digit', minute: '2-digit' })
    };

    setVentasDelDia([...ventasDelDia, nuevaVenta]);
  };

  const limpiarCierreCaja = () => {
    if (window.confirm("¿Seguro que deseas cerrar la jornada actual? Esto limpiará el reporte de hoy.")) {
      setVentasDelDia([]);
      localStorage.removeItem('ventas_paisita');
    }
  };

  const formatearMoneda = (v) => new Intl.NumberFormat('es-CO', { style: 'currency', currency: 'COP', minimumFractionDigits: 0 }).format(v || 0);
  const ingresosTotales = ventasDelDia.reduce((sum, v) => sum + (v.precioVenta || 0), 0);
  const gananciasTotalesNetas = ventasDelDia.reduce((sum, v) => sum + (v.gananciaNeta || 0), 0);

  // --- RENDERIZADO LOGIN (DISEÑO PROFESIONAL) ---
  if (!isLoggedIn) {
    return (
      <div style={{ 
        display: 'flex', alignItems: 'center', justifyContent: 'center', height: '100vh', 
        background: '#1a1a1a', fontFamily: 'Segoe UI, Tahoma, Geneva, Verdana, sans-serif' 
      }}>
        <div style={{ 
          background: '#ffffff', padding: '40px', borderRadius: '15px', 
          boxShadow: '0 10px 30px rgba(0,0,0,0.5)', width: '300px', textAlign: 'center' 
        }}>
          <h2 style={{ color: '#333', marginBottom: '25px', marginTop: '0' }}>Acceso Admin</h2>
          <input 
            type="text" placeholder="Usuario" value={username} 
            onChange={(e) => setUsername(e.target.value)}
            style={{ width: '100%', padding: '12px', marginBottom: '15px', borderRadius: '6px', border: '1px solid #ddd', boxSizing: 'border-box' }}
          />
          <input 
            type="password" placeholder="Contraseña" value={password} 
            onChange={(e) => setPassword(e.target.value)}
            style={{ width: '100%', padding: '12px', marginBottom: '25px', borderRadius: '6px', border: '1px solid #ddd', boxSizing: 'border-box' }}
          />
          <button 
            onClick={() => {
              if (username === 'admin' && password === '12345') setIsLoggedIn(true);
              else alert('Credenciales incorrectas');
            }}
            style={{ 
              width: '100%', padding: '12px', background: '#e67e22', color: 'white', 
              border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', fontSize: '15px',
              transition: 'background 0.3s'
            }}
          >
            Ingresar
          </button>
        </div>
      </div>
    );
  }

  // --- RENDERIZADO PRINCIPAL ---
  return (
    <div className="app-layout">
      <header className="app-header">
        <div className="header-brand">
          <h1>El Paisita UP</h1>
          <p className="fecha-badge">📅 {fechaHoy}</p>
        </div>
        <nav className="header-nav">
          <button className={`nav-link ${pantalla === 'catalogo' ? 'active' : ''}`} onClick={() => setPantalla('catalogo')}>📦 Catálogo</button>
          <button className={`nav-link ${pantalla === 'formulario' ? 'active' : ''}`} onClick={() => setPantalla('formulario')}>➕ Ingresar Mercancía</button>
          <button className={`nav-link-alert ${pantalla === 'reporte' ? 'active' : ''}`} onClick={() => setPantalla('reporte')}>📊 Cierre de Caja ({ventasDelDia.length})</button>
          <button className="btn-nav-clear-database" onClick={handleBorrarTodo}>🔥 Reiniciar Todo</button>
        </nav>
      </header>

      <main className="app-content">
        {pantalla === 'catalogo' && (
          <div className="catalogo-view">
            <div className="seccion-titulo">
              <h2>Inventario Disponible</h2>
              <p>Módulo de facturación directa y alteración física de stock por ítem</p>
            </div>

            {productos.length === 0 ? (
              <div className="empty-state">No hay mercancía en el catálogo. Registra un ítem.</div>
            ) : (
              <div className="grid-catalogo">
                {productos.map((prod) => (
                  <div key={prod.id} className="card-producto">
                    <div className="card-image-wrapper">
                      <img src={prod.imagenUrl} alt={prod.nombre} onError={(e)=>{e.target.src="https://images.unsplash.com/photo-1546069901-ba9599a7e63c"}} />
                      <span className="categoria-tag">{prod.categoria}</span>
                    </div>
                    <div className="card-info">
                      <h3>{prod.nombre}</h3>
                      <div className="card-precios">
                        <div>
                          <span className="label-precio">P. Venta</span>
                          <span className="valor-venta">{formatearMoneda(prod.precioVenta || 0)}</span>
                        </div>
                        <div className="text-right">
                          <span className="label-precio">Costo base</span>
                          <span className="valor-costo">{formatearMoneda(prod.precioCosto || 0)}</span>
                        </div>
                      </div>

                      <div className="stock-status-bar">
                        <span className="stock-count">Existencia: <strong>{prod.stock} uds</strong></span>
                      </div>

                      <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '8px' }}>
                        <button className="btn-vender-card" onClick={() => registrarVenta(prod)} disabled={(prod.stock || 0) <= 0}>
                          {(prod.stock || 0) <= 0 ? '🚫 Agotado' : '🛒 Vender'}
                        </button>
                        <button className="btn-modificar-stock" onClick={() => cambiarStockManual(prod)} title="Ajustar inventario físico">
                          ✏️ Stock
                        </button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {pantalla === 'formulario' && (
          <div className="form-container-centered">
            <div className="form-card">
              <h2 className="form-title">Registro Único de Producto</h2>
              <form onSubmit={handleGuardar}>
                <div className="form-group">
                  <label className="form-label">Nombre del Producto</label>
                  <input type="text" value={nombre} onChange={(e) => setNombre(e.target.value)} className="form-input" required />
                </div>
                <div className="grid-2-col">
                  <div className="form-group">
                    <label className="form-label">Categoría</label>
                    <input type="text" value={categoria} onChange={(e) => setCategoria(e.target.value)} className="form-input" />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Imagen (URL)</label>
                    <input type="text" value={imagenUrl} onChange={(e) => setImagenUrl(e.target.value)} className="form-input" />
                  </div>
                </div>
                <div className="grid-2-col">
                  <div className="form-group">
                    <label className="form-label">Precio Costo</label>
                    <input type="number" value={precioCosto} onChange={(e) => setPrecioCosto(e.target.value)} className="form-input" />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Impuesto</label>
                    <select value={impuesto} onChange={(e) => setImpuesto(e.target.value)} className="form-input">
                      <option value="19">IVA 19%</option>
                      <option value="8">INC 8%</option>
                      <option value="0">Exento</option>
                    </select>
                  </div>
                </div>
                <div className="grid-2-col">
                  <div className="form-group">
                    <label className="form-label">Precio Final Venta</label>
                    <input type="number" value={precioVenta} onChange={(e) => setPrecioVenta(e.target.value)} className="form-input" />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Cantidad Inicial</label>
                    <input type="number" value={stock} onChange={(e) => setStock(e.target.value)} className="form-input" />
                  </div>
                </div>
                <button type="submit" className="btn-submit">Inyectar Nuevo Producto</button>
              </form>
            </div>
          </div>
        )}

        {pantalla === 'reporte' && (
          <div className="reporte-view">
            <div className="kpi-dashboard">
              <div className="kpi-card text-pastel-pink">
                <h3>Volumen de Ventas</h3>
                <p className="kpi-valor">{ventasDelDia.length} uds</p>
              </div>
              <div className="kpi-card text-pastel-blue">
                <h3>Recaudo de Caja</h3>
                <p className="kpi-valor">{formatearMoneda(ingresosTotales)}</p>
              </div>
              <div className="kpi-card text-pastel-green">
                <h3>Utilidad Neta</h3>
                <p className="kpi-valor">{formatearMoneda(gananciasTotalesNetas)}</p>
              </div>
            </div>
            <div className="form-card full-width-card">
              <div className="reporte-header">
                <h2>Cierre Diario de Operaciones</h2>
                <button className="btn-clean-caja" onClick={limpiarCierreCaja}>🔒 Cerrar Caja</button>
              </div>
              {ventasDelDia.length === 0 ? (
                <p className="empty-state">No hay registros de transacciones para la fecha.</p>
              ) : (
                <table className="tabla-reporte">
                  <thead>
                    <tr>
                      <th>Timestamp</th>
                      <th>Ítem</th>
                      <th>Ingreso Bruto</th>
                      <th>Ganancia</th>
                    </tr>
                  </thead>
                  <tbody>
                    {ventasDelDia.map((v) => (
                      <tr key={v.id}>
                        <td>{v.hora}</td>
                        <td>{v.nombre}</td>
                        <td>{formatearMoneda(v.precioVenta)}</td>
                        <td>{formatearMoneda(v.gananciaNeta)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

export default App;
